","/* ═══════════════════════════════════════════════════
 Schedule Planner — styles.css
 All classes prefixed with .sp-
 ═══════════════════════════════════════════════════ */

/* ── Shell ── */

.sp-shell {
 font-family: var(--now-font-family, "Source Sans Pro", Arial, sans-serif);
 color: var(--now-color_text--primary, #1e1e1e);
 background: var(--now-color_background--primary, #ffffff);
 min-height: 100vh;
 padding: var(--now-static-space--lg, 24px);
 box-sizing: border-box;
}

/* ── Header ── */

.sp-header {
 margin: 0 0 var(--now-static-space--lg, 24px) 0;
}

.sp-header-title {
 margin: 0;
 font-size: var(--now-static-font-size--lg, 20px);
 font-weight: 600;
 color: var(--now-color_text--primary, #1e1e1e);
}

.sp-header-sub {
 margin: var(--now-static-space--xxs, 2px) 0 0 0;
 font-size: var(--now-static-font-size--sm, 12px);
 color: var(--now-color_text--secondary, #6b6b6b);
}

/* ── Content ── */

.sp-content {
 display: flex;
 flex-direction: column;
 gap: var(--now-static-space--md, 16px);
}

/* ── Action messages ── */

.sp-msg {
 padding: var(--now-static-space--sm, 8px) var(--now-static-space--md, 16px);
 border-radius: 4px;
 font-size: var(--now-static-font-size--sm, 12px);
 margin-bottom: var(--now-static-space--sm, 8px);
}

.sp-msg--success {
 background: #c8e6c9;
 color: #2e7d32;
 border: 1px solid #a5d6a7;
}

.sp-msg--error {
 background: #ffcdd2;
 color: #b71c1c;
 border: 1px solid #ef9a9a;
}

/* ── Collapsible Filters ── */

.sp-filters {
 background: var(--now-color_background--secondary, #f4f4f4);
 border: 1px solid var(--now-container--border-color, #d6d6d6);
 border-radius: 4px;
 padding: var(--now-static-space--sm, 8px) var(--now-static-space--md, 16px);
}

.sp-filter-toggle {
 background: none;
 border: none;
 color: var(--now-color_text--primary, #1e1e1e);
 font-family: var(--now-font-family, "Source Sans Pro", Arial, sans-serif);
 font-size: var(--now-static-font-size--sm, 12px);
 font-weight: 600;
 cursor: pointer;
 padding: var(--now-static-space--xxs, 2px) 0;
}

.sp-filter-toggle:hover {
 text-decoration: underline;
}

.sp-filter-row {
 display: flex;
 flex-wrap: wrap;
 gap: var(--now-static-space--md, 16px);
 margin-top: var(--now-static-space--sm, 8px);
}

.sp-filter-field {
 display: flex;
 flex-direction: column;
 gap: var(--now-static-space--xxs, 2px);
 min-width: 160px;
 flex: 1;
}

.sp-filter-field label {
 font-size: var(--now-static-font-size--sm, 12px);
 font-weight: 600;
 color: var(--now-color_text--secondary, #6b6b6b);
}

.sp-input {
 font-family: var(--now-font-family, "Source Sans Pro", Arial, sans-serif);
 font-size: var(--now-static-font-size--sm, 12px);
 padding: var(--now-static-space--xs, 4px) var(--now-static-space--sm, 8px);
 border: 1px solid var(--now-container--border-color, #d6d6d6);
 border-radius: 4px;
 background: var(--now-color_background--primary, #ffffff);
 color: var(--now-color_text--primary, #1e1e1e);
 box-sizing: border-box;
}

.sp-input:focus {
 outline: 2px solid #0080a3;
 outline-offset: -1px;
}

/* ── KPI Cards ── */

.sp-cards {
 display: grid;
 grid-template-columns: repeat(auto-fill, minmax(150px, 1fr));
 gap: var(--now-static-space--sm, 8px);
}

.sp-card {
 background: var(--now-color_background--primary, #ffffff);
 border: 1px solid var(--now-container--border-color, #d6d6d6);
 border-radius: 6px;
 padding: var(--now-static-space--md, 16px);
 text-align: center;
}

.sp-card-value {
 font-size: var(--now-static-font-size--lg, 20px);
 font-weight: 700;
 color: var(--now-color_text--primary, #1e1e1e);
}

.sp-card-label {
 font-size: var(--now-static-font-size--sm, 12px);
 color: var(--now-color_text--secondary, #6b6b6b);
 margin-top: var(--now-static-space--xxs, 2px);
}

.sp-card--ok {
 border-left: 4px solid #2e7d32;
}

.sp-card--ok .sp-card-value {
 color: #2e7d32;
}

.sp-card--warn {
 border-left: 4px solid #f57f17;
}

.sp-card--warn .sp-card-value {
 color: #f57f17;
}

.sp-card--danger {
 border-left: 4px solid #b71c1c;
}

.sp-card--danger .sp-card-value {
 color: #b71c1c;
}

/* ── Tabs ── */

.sp-tabs {
 display: flex;
 gap: 0;
 border-bottom: 2px solid var(--now-container--border-color, #d6d6d6);
}

.sp-tab {
 font-family: var(--now-font-family, "Source Sans Pro", Arial, sans-serif);
 font-size: var(--now-static-font-size--sm, 12px);
 font-weight: 600;
 padding: var(--now-static-space--sm, 8px) var(--now-static-space--md, 16px);
 border: none;
 background: none;
 color: var(--now-color_text--secondary, #6b6b6b);
 cursor: pointer;
 border-bottom: 2px solid transparent;
 margin-bottom: -2px;
 transition: color 0.15s, border-color 0.15s;
}

.sp-tab:hover {
 color: var(--now-color_text--primary, #1e1e1e);
}

.sp-tab.active {
 color: #0080a3;
 border-bottom-color: #0080a3;
}

/* ── Section Title ── */

.sp-section-title {
 font-size: var(--now-static-font-size--lg, 20px);
 font-weight: 600;
 margin: var(--now-static-space--md, 16px) 0 var(--now-static-space--sm, 8px) 0;
 color: var(--now-color_text--primary, #1e1e1e);
}

/* ── Table ── */

.sp-table-wrap {
 overflow-x: auto;
}

.sp-table {
 width: 100%;
 border-collapse: collapse;
 font-size: var(--now-static-font-size--sm, 12px);
}

.sp-table th,
.sp-table td {
 text-align: left;
 padding: var(--now-static-space--sm, 8px) var(--now-static-space--sm, 8px);
 border-bottom: 1px solid var(--now-container--border-color, #d6d6d6);
 white-space: nowrap;
}

.sp-table th {
 font-weight: 600;
 color: var(--now-color_text--secondary, #6b6b6b);
 background: var(--now-color_background--secondary, #f4f4f4);
 position: sticky;
 top: 0;
}

.sp-table tbody tr:hover {
 background: var(--now-color_background--secondary, #f4f4f4);
}

/* ── Badges ── */

.sp-badge {
 display: inline-block;
 padding: var(--now-static-space--xxs, 2px) var(--now-static-space--sm, 8px);
 border-radius: 12px;
 font-size: var(--now-static-font-size--sm, 12px);
 font-weight: 600;
 text-transform: capitalize;
 white-space: nowrap;
}

.sp-badge-ok {
 background: #c8e6c9;
 color: #2e7d32;
}

.sp-badge-warn {
 background: #fff9c4;
 color: #f57f17;
}

.sp-badge-danger {
 background: #ffcdd2;
 color: #b71c1c;
}

.sp-badge-neutral {
 background: #e0e0e0;
 color: #424242;
}

/* ── Resource Grid ── */

.sp-res-grid {
 display: grid;
 grid-template-columns: repeat(auto-fill, minmax(240px, 1fr));
 gap: var(--now-static-space--md, 16px);
}

.sp-res-card {
 background: var(--now-color_background--primary, #ffffff);
 border: 1px solid var(--now-container--border-color, #d6d6d6);
 border-radius: 6px;
 padding: var(--now-static-space--md, 16px);
 display: flex;
 flex-direction: column;
 gap: var(--now-static-space--xs, 4px);
}

.sp-res-name {
 font-size: var(--now-static-font-size--lg, 20px);
 font-weight: 600;
 color: var(--now-color_text--primary, #1e1e1e);
 margin-bottom: var(--now-static-space--xxs, 2px);
}

.sp-res-detail {
 font-size: var(--now-static-font-size--sm, 12px);
 color: var(--now-color_text--secondary, #6b6b6b);
}

.sp-res-detail strong {
 color: var(--now-color_text--primary, #1e1e1e);
}

.sp-res-badge {
 display: inline-block;
 align-self: flex-start;
 padding: var(--now-static-space--xxs, 2px) var(--now-static-space--sm, 8px);
 border-radius: 12px;
 font-size: var(--now-static-font-size--sm, 12px);
 font-weight: 600;
 color: #424242;
 text-transform: capitalize;
}

/* ── Actions column ── */

.sp-actions {
 white-space: nowrap;
}

/* ── Empty / Loading / Error states ── */

.sp-empty {
 text-align: center;
 padding: var(--now-static-space--lg, 24px);
 color: var(--now-color_text--secondary, #6b6b6b);
 font-size: var(--now-static-font-size--sm, 12px);
 background: var(--now-color_background--secondary, #f4f4f4);
 border-radius: 6px;
}

.sp-loading {
 text-align: center;
 padding: var(--now-static-space--lg, 24px) 0;
 font-size: var(--now-static-font-size--lg, 20px);
 color: var(--now-color_text--secondary, #6b6b6b);
}

.sp-error {
 text-align: center;
 padding: var(--now-static-space--lg, 24px);
 color: #b71c1c;
 background: #ffcdd2;
 border-radius: 6px;
}

.sp-error p {
 margin: 0 0 var(--now-static-space--sm, 8px) 0;
}
","export default function insertStyle(css, tagName = "style") {
 if (!css || typeof window === "undefined")
 return;
 if (tagName === "style") {
 const style = document.createElement("style");
 style.setAttribute("type", "text/css");
 style.innerHTML = css;
 document.head.appendChild(style);
 }
 else if (tagName === "link") {
 const link = document.createElement("link");
 link.setAttribute("rel", "stylesheet");
 link.setAttribute("href", css);
 document.head.appendChild(link);
 }
 return css;
}","import React, { useState, useEffect, useCallback } from "react";
import { Button } from "@servicenow/react-components/Button";
import "./styles.css";

/* ───────── constants ───────── */

const API_BASE = "/api/x_2056099_indust_0/operator_api";

/* ───────── types ───────── */

interface Conflict {
 type: string;
 message: string;
}

interface Schedule {
 sys_id: string;
 number: string;
 status: string;
 statusDisplay: string;
 priority: string;
 priorityDisplay: string;
 planned_start: string;
 planned_end: string;
 planned_quantity: number;
 duration_days: number;
 po_id: string;
 po_number: string;
 po_status: string;
 finished_product: string;
 res_id: string;
 res_name: string;
 res_type: string;
 res_status: string;
 resource_feasibility: string;
 delivery_date: string;
 delivery_status: string;
 conflicts: Conflict[];
 health: string;
 health_details: string[];
}

interface Resource {
 sys_id: string;
 name: string;
 resource_id: string;
 resource_type: string;
 status: string;
 statusDisplay: string;
 capacity_per_day: number;
 efficiency: number;
 maintenance_required: boolean;
 scheduled_days: number;
}

interface UnscheduledOrder {
 sys_id: string;
 number: string;
 status: string;
 statusDisplay: string;
 finished_product: string;
 priority: string;
 priorityDisplay: string;
 quantity_planned: number;
}

interface Summary {
 totalSchedules: number;
 feasible: number;
 conflicts: number;
 risks: number;
 totalResources: number;
 unscheduledOrders: number;
}

type Tab = "schedules" | "resources" | "unscheduled";

/* ───────── health badge helpers ───────── */

const HEALTH_STYLES: Record<string, { bg: string; color: string }> = {
 feasible: { bg: "#c8e6c9", color: "#2e7d32" },
 conflict: { bg: "#ffcdd2", color: "#b71c1c" },
 delivery_risk: { bg: "#fff9c4", color: "#f57f17" },
 capacity_shortage: { bg: "#ffe0b2", color: "#e65100" },
 maintenance: { bg: "#e0e0e0", color: "#424242" },
 resource_unavailable: { bg: "#f5f5f5", color: "#9e9e9e" },
};

const RES_STATUS_COLORS: Record<string, string> = {
 available: "#c8e6c9",
 maintenance: "#ffe0b2",
 unavailable: "#ffcdd2",
 busy: "#bbdefb",
};

function healthBadgeClass(health: string): string {
 if (health === "feasible") return "sp-badge sp-badge-ok";
 if (health === "conflict") return "sp-badge sp-badge-danger";
 if (health === "delivery_risk" || health === "capacity_shortage")
 return "sp-badge sp-badge-warn";
 return "sp-badge sp-badge-neutral";
}

function healthBadgeStyle(health: string): React.CSSProperties {
 const s = HEALTH_STYLES[health];
 return s ? { backgroundColor: s.bg, color: s.color } : {};
}

function fmtDate(d: string): string {
 if (!d) return "—";
 try {
 return new Date(d).toLocaleDateString();
 } catch {
 return d;
 }
}

/* ───────── component ───────── */

export default function App() {
 /* data */
 const [schedules, setSchedules] = useState<Schedule[]>([]);
 const [resources, setResources] = useState<Resource[]>([]);
 const [unscheduledOrders, setUnscheduledOrders] = useState<UnscheduledOrder[]>([]);
 const [summary, setSummary] = useState<Summary | null>(null);

 /* ui state */
 const [loading, setLoading] = useState(true);
 const [error, setError] = useState("");
 const [activeTab, setActiveTab] = useState<Tab>("schedules");
 const [filtersOpen, setFiltersOpen] = useState(false);
 const [actionLoading, setActionLoading] = useState(false);
 const [actionMsg, setActionMsg] = useState<{
 type: "success" | "error";
 text: string;
 } | null>(null);

 /* filters */
 const [statusFilter, setStatusFilter] = useState("all");
 const [resourceFilter, setResourceFilter] = useState("all");
 const [healthFilter, setHealthFilter] = useState("all");
 const [searchText, setSearchText] = useState("");

 /* ── fetch ── */

 const fetchData = useCallback(async () => {
 setLoading(true);
 setError("");
 try {
 const res = await fetch(`${API_BASE}/schedule-planner-data`, {
 headers: {
 Accept: "application/json",
 "X-UserToken": (window as any).g_ck || "",
 },
 });
 if (!res.ok) throw new Error(`HTTP ${res.status}`);
 const json = await res.json();
 const d = json.result;
 if (!d || !d.success) throw new Error("API returned unsuccessful response");
 setSchedules(d.schedules || []);
 setResources(d.resources || []);
 setUnscheduledOrders(d.unscheduledOrders || []);
 setSummary(d.summary || null);
 } catch (e: any) {
 setError(e.message || "Failed to load data");
 } finally {
 setLoading(false);
 }
 }, []);

 useEffect(() => {
 fetchData();
 }, [fetchData]);

 /* auto-clear action message */
 useEffect(() => {
 if (actionMsg) {
 const t = setTimeout(() => setActionMsg(null), 5000);
 return () => clearTimeout(t);
 }
 }, [actionMsg]);

 /* ── actions ── */

 async function confirmSchedule(scheduleId: string) {
 setActionLoading(true);
 setActionMsg(null);
 try {
 const res = await fetch(`${API_BASE}/confirm-schedule`, {
 method: "POST",
 headers: {
 "Content-Type": "application/json",
 Accept: "application/json",
 "X-UserToken": (window as any).g_ck || "",
 },
 body: JSON.stringify({ schedule_id: scheduleId }),
 });
 if (!res.ok) throw new Error(`HTTP ${res.status}`);
 const json = await res.json();
 setActionMsg({
 type: "success",
 text: json.result?.message || "Schedule confirmed successfully",
 });
 await fetchData();
 } catch (e: any) {
 setActionMsg({
 type: "error",
 text: e.message || "Failed to confirm schedule",
 });
 } finally {
 setActionLoading(false);
 }
 }

 async function createSchedule(poId: string) {
 setActionLoading(true);
 setActionMsg(null);
 try {
 const res = await fetch(`${API_BASE}/create-schedule`, {
 method: "POST",
 headers: {
 "Content-Type": "application/json",
 Accept: "application/json",
 "X-UserToken": (window as any).g_ck || "",
 },
 body: JSON.stringify({ production_order_id: poId }),
 });
 if (!res.ok) throw new Error(`HTTP ${res.status}`);
 const json = await res.json();
 setActionMsg({
 type: "success",
 text: json.result?.message || "Schedule created successfully",
 });
 await fetchData();
 } catch (e: any) {
 setActionMsg({
 type: "error",
 text: e.message || "Failed to create schedule",
 });
 } finally {
 setActionLoading(false);
 }
 }

 /* ── filtering ── */

 const filteredSchedules = schedules.filter((s) => {
 if (statusFilter !== "all" && s.status !== statusFilter) return false;
 if (resourceFilter !== "all" && s.res_id !== resourceFilter) return false;
 if (healthFilter !== "all") {
 if (healthFilter === "feasible" && s.health !== "feasible") return false;
 if (healthFilter === "conflict" && s.health !== "conflict") return false;
 if (
 healthFilter === "risks" &&
 ![
 "delivery_risk",
 "capacity_shortage",
 "maintenance",
 "resource_unavailable",
 ].includes(s.health)
 )
 return false;
 }
 if (searchText) {
 const q = searchText.toLowerCase();
 const matchesPo = (s.po_number || "").toLowerCase().includes(q);
 const matchesProduct = (s.finished_product || "").toLowerCase().includes(q);
 if (!matchesPo && !matchesProduct) return false;
 }
 return true;
 });

 /* ── tab renderers ── */

 function renderSchedulesTab() {
 if (filteredSchedules.length === 0) {
 return (
 <div className="sp-empty">
 No production schedules found. Create Production Orders and use the
 scheduling actions to generate schedules.
 </div>
 );
 }
 return (
 <div className="sp-table-wrap">
 <table className="sp-table">
 <thead>
 <tr>
 <th>Schedule</th>
 <th>Order</th>
 <th>Product</th>
 <th>Resource</th>
 <th>Start</th>
 <th>End</th>
 <th>Qty</th>
 <th>Priority</th>
 <th>Status</th>
 <th>Health</th>
 <th>Actions</th>
 </tr>
 </thead>
 <tbody>
 {filteredSchedules.map((s) => (
 <tr key={s.sys_id}>
 <td>{s.number}</td>
 <td>{s.po_number}</td>
 <td>{s.finished_product}</td>
 <td>{s.res_name}</td>
 <td>{fmtDate(s.planned_start)}</td>
 <td>{fmtDate(s.planned_end)}</td>
 <td>{s.planned_quantity}</td>
 <td>{s.priorityDisplay || s.priority}</td>
 <td>{s.statusDisplay || s.status}</td>
 <td>
 <span
 className={healthBadgeClass(s.health)}
 style={healthBadgeStyle(s.health)}
 title={
 s.health_details && s.health_details.length > 0
 ? s.health_details.join("; ")
 : s.health
 }
 >
 {(s.health || "unknown").replace(/_/g, " ")}
 </span>
 </td>
 <td className="sp-actions">
 {s.status === "draft" && (
 <Button
 label="Confirm"
 disabled={actionLoading}
 onClick={() => confirmSchedule(s.sys_id)}
 />
 )}
 </td>
 </tr>
 ))}
 </tbody>
 </table>
 </div>
 );
 }

 function renderResourcesTab() {
 if (resources.length === 0) {
 return <div className="sp-empty">No resources found.</div>;
 }
 return (
 <div className="sp-res-grid">
 {resources.map((r) => (
 <div key={r.sys_id} className="sp-res-card">
 <div className="sp-res-name">{r.name}</div>
 <span
 className="sp-res-badge"
 style={{
 backgroundColor: RES_STATUS_COLORS[r.status] || "#e0e0e0",
 }}
 >
 {r.statusDisplay || r.status}
 </span>
 <div className="sp-res-detail">
 <strong>Type:</strong> {r.resource_type}
 </div>
 <div className="sp-res-detail">
 <strong>Capacity/Day:</strong> {r.capacity_per_day}
 </div>
 <div className="sp-res-detail">
 <strong>Efficiency:</strong>{" "}
 {r.efficiency || 0}%
 </div>
 <div className="sp-res-detail">
 <strong>Maintenance:</strong>{" "}
 {r.maintenance_required ? "Yes" : "No"}
 </div>
 <div className="sp-res-detail">
 <strong>Scheduled Days:</strong> {r.scheduled_days}
 </div>
 </div>
 ))}
 </div>
 );
 }

 function renderUnscheduledTab() {
 if (unscheduledOrders.length === 0) {
 return <div className="sp-empty">No unscheduled orders.</div>;
 }
 return (
 <div className="sp-table-wrap">
 <table className="sp-table">
 <thead>
 <tr>
 <th>Order</th>
 <th>Product</th>
 <th>Priority</th>
 <th>Status</th>
 <th>Quantity</th>
 <th>Actions</th>
 </tr>
 </thead>
 <tbody>
 {unscheduledOrders.map((o) => (
 <tr key={o.sys_id}>
 <td>{o.number}</td>
 <td>{o.finished_product}</td>
 <td>{o.priorityDisplay || o.priority}</td>
 <td>{o.statusDisplay || o.status}</td>
 <td>{o.quantity_planned}</td>
 <td className="sp-actions">
 <Button
 label="Create Schedule"
 disabled={actionLoading}
 onClick={() => createSchedule(o.sys_id)}
 />
 </td>
 </tr>
 ))}
 </tbody>
 </table>
 </div>
 );
 }

 /* ── top-level states ── */

 if (loading) {
 return (
 <div className="sp-shell">
 <div className="sp-loading">Loading schedule data…</div>
 </div>
 );
 }

 if (error) {
 return (
 <div className="sp-shell">
 <div className="sp-error">
 <p>Error: {error}</p>
 <Button label="Retry" onClick={() => fetchData()} />
 </div>
 </div>
 );
 }

 /* ── main render ── */

 return (
 <div className="sp-shell">
 <header className="sp-header">
 <h1 className="sp-header-title">Schedule Planner</h1>
 <p className="sp-header-sub">Production Schedule Overview</p>
 </header>

 {actionMsg && (
 <div
 className={`sp-msg ${
 actionMsg.type === "success" ? "sp-msg--success" : "sp-msg--error"
 }`}
 >
 {actionMsg.text}
 </div>
 )}

 <div className="sp-content">
 {/* ── Collapsible Filters ── */}
 <div className="sp-filters">
 <button
 className="sp-filter-toggle"
 onClick={() => setFiltersOpen(!filtersOpen)}
 >
 {filtersOpen ? "▾ Hide Filters" : "▸ Show Filters"}
 </button>

 {filtersOpen && (
 <div className="sp-filter-row">
 <div className="sp-filter-field">
 <label>Status</label>
 <select
 className="sp-input"
 value={statusFilter}
 onChange={(e) => setStatusFilter(e.target.value)}
 >
 <option value="all">All Statuses</option>
 <option value="draft">Draft</option>
 <option value="scheduled">Scheduled</option>
 <option value="confirmed">Confirmed</option>
 <option value="in_progress">In Progress</option>
 </select>
 </div>

 <div className="sp-filter-field">
 <label>Resource</label>
 <select
 className="sp-input"
 value={resourceFilter}
 onChange={(e) => setResourceFilter(e.target.value)}
 >
 <option value="all">All Resources</option>
 {resources.map((r) => (
 <option key={r.sys_id} value={r.sys_id}>
 {r.name}
 </option>
 ))}
 </select>
 </div>

 <div className="sp-filter-field">
 <label>Health</label>
 <select
 className="sp-input"
 value={healthFilter}
 onChange={(e) => setHealthFilter(e.target.value)}
 >
 <option value="all">All Health</option>
 <option value="feasible">Feasible</option>
 <option value="conflict">Conflicts</option>
 <option value="risks">Risks</option>
 </select>
 </div>

 <div className="sp-filter-field">
 <label>Search</label>
 <input
 className="sp-input"
 type="text"
 placeholder="PO number or product…"
 value={searchText}
 onChange={(e) => setSearchText(e.target.value)}
 />
 </div>
 </div>
 )}
 </div>

 {/* ── KPI Cards ── */}
 {summary && (
 <div className="sp-cards">
 <div className="sp-card">
 <div className="sp-card-value">{summary.totalSchedules}</div>
 <div className="sp-card-label">Total Schedules</div>
 </div>
 <div className="sp-card sp-card--ok">
 <div className="sp-card-value">{summary.feasible}</div>
 <div className="sp-card-label">Feasible</div>
 </div>
 <div className="sp-card sp-card--danger">
 <div className="sp-card-value">{summary.conflicts}</div>
 <div className="sp-card-label">Conflicts</div>
 </div>
 <div className="sp-card sp-card--warn">
 <div className="sp-card-value">{summary.risks}</div>
 <div className="sp-card-label">Risks</div>
 </div>
 <div className="sp-card">
 <div className="sp-card-value">{summary.unscheduledOrders}</div>
 <div className="sp-card-label">Unscheduled Orders</div>
 </div>
 <div className="sp-card">
 <div className="sp-card-value">{summary.totalResources}</div>
 <div className="sp-card-label">Total Resources</div>
 </div>
 </div>
 )}

 {/* ── Tabs ── */}
 <div className="sp-tabs">
 <button
 className={`sp-tab${activeTab === "schedules" ? " active" : ""}`}
 onClick={() => setActiveTab("schedules")}
 >
 Schedules
 </button>
 <button
 className={`sp-tab${activeTab === "resources" ? " active" : ""}`}
 onClick={() => setActiveTab("resources")}
 >
 Resources
 </button>
 <button
 className={`sp-tab${activeTab === "unscheduled" ? " active" : ""}`}
 onClick={() => setActiveTab("unscheduled")}
 >
 Unscheduled Orders
 </button>
 </div>

 {/* ── Tab content ── */}
 {activeTab === "schedules" && renderSchedulesTab()}
 {activeTab === "resources" && renderResourcesTab()}
 {activeTab === "unscheduled" && renderUnscheduledTab()}
 </div>
 </div>
 );
}
